import React, { useState } from 'react';
import { CartItem, InvoiceDetails } from '../types';

interface InvoiceModalProps {
  cart: CartItem[];
  onClose: () => void;
  onClearCart: () => void;
}

const InvoiceModal: React.FC<InvoiceModalProps> = ({ cart, onClose, onClearCart }) => {
  const [customerName, setCustomerName] = useState('');
  const [isGenerated, setIsGenerated] = useState(false);

  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const orderId = Math.random().toString(36).substring(2, 9).toUpperCase();
  const date = new Date().toLocaleDateString('en-US', { 
    year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' 
  });

  const handleGenerate = (e: React.FormEvent) => {
    e.preventDefault();
    if (customerName.trim()) {
      setIsGenerated(true);
    }
  };

  const getInvoiceText = () => {
    let text = `*BistroCloud Invoice - #${orderId}*\n`;
    text += `Customer: ${customerName}\n`;
    text += `Date: ${date}\n`;
    text += `--------------------------\n`;
    cart.forEach(item => {
      text += `${item.name} x${item.quantity} - $${(item.price * item.quantity).toFixed(2)}\n`;
    });
    text += `--------------------------\n`;
    text += `*Total: $${total.toFixed(2)}*\n\n`;
    text += `Thank you for dining with us!`;
    return encodeURIComponent(text);
  };

  const shareWhatsApp = () => {
    window.open(`https://wa.me/?text=${getInvoiceText()}`, '_blank');
  };

  const shareSMS = () => {
    window.location.href = `sms:?body=${getInvoiceText()}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <div className="bg-white w-full max-w-md rounded-3xl overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-300">
        {!isGenerated ? (
          <div className="p-8">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Complete Order</h2>
            <form onSubmit={handleGenerate}>
              <div className="mb-6">
                <label className="block text-sm font-medium text-slate-600 mb-2">Customer Name</label>
                <input
                  type="text"
                  required
                  value={customerName}
                  onChange={(e) => setCustomerName(e.target.value)}
                  placeholder="Enter name for invoice"
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 focus:border-transparent outline-none transition-all"
                />
              </div>
              <div className="flex gap-3">
                <button 
                  type="button"
                  onClick={onClose}
                  className="flex-1 py-3 px-4 rounded-xl border border-slate-200 font-medium text-slate-600 hover:bg-slate-50 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className="flex-1 py-3 px-4 rounded-xl bg-indigo-600 text-white font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100"
                >
                  Generate Invoice
                </button>
              </div>
            </form>
          </div>
        ) : (
          <div className="max-h-[85vh] flex flex-col">
            <div className="p-8 overflow-y-auto flex-1">
              <div className="flex justify-between items-start mb-8">
                <div>
                  <h2 className="text-xl font-bold text-slate-900">INVOICE</h2>
                  <p className="text-sm text-slate-500">#{orderId}</p>
                </div>
                <div className="text-right">
                  <div className="w-12 h-12 bg-indigo-600 rounded-xl flex items-center justify-center text-white ml-auto">
                    <i className="fas fa-utensils"></i>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4 mb-8">
                <div>
                  <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Bill To</p>
                  <p className="font-bold text-slate-800">{customerName}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Date</p>
                  <p className="font-medium text-slate-800 text-sm">{date}</p>
                </div>
              </div>

              <div className="border-t border-b border-slate-100 py-4 mb-6">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-slate-400 font-medium">
                      <th className="pb-4">Item</th>
                      <th className="pb-4 text-center">Qty</th>
                      <th className="pb-4 text-right">Amount</th>
                    </tr>
                  </thead>
                  <tbody className="text-slate-800">
                    {cart.map((item) => (
                      <tr key={item.id}>
                        <td className="py-2">{item.name}</td>
                        <td className="py-2 text-center">{item.quantity}</td>
                        <td className="py-2 text-right">${(item.price * item.quantity).toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="flex justify-between items-center mb-8">
                <span className="text-slate-500 font-medium">Grand Total</span>
                <span className="text-2xl font-black text-indigo-600">${total.toFixed(2)}</span>
              </div>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200">
              <p className="text-center text-xs text-slate-500 mb-6">Share this invoice with your customer</p>
              <div className="grid grid-cols-2 gap-3 mb-3">
                <button 
                  onClick={shareWhatsApp}
                  className="flex items-center justify-center gap-2 py-3 bg-[#25D366] text-white rounded-xl font-bold hover:opacity-90 transition-opacity"
                >
                  <i className="fab fa-whatsapp text-lg"></i>
                  WhatsApp
                </button>
                <button 
                  onClick={shareSMS}
                  className="flex items-center justify-center gap-2 py-3 bg-slate-800 text-white rounded-xl font-bold hover:opacity-90 transition-opacity"
                >
                  <i className="fas fa-comment-alt text-lg"></i>
                  Message
                </button>
              </div>
              <button 
                onClick={() => {
                  onClearCart();
                  onClose();
                }}
                className="w-full py-3 text-slate-500 font-semibold text-sm hover:text-slate-700 transition-colors"
              >
                Close & Start New Order
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default InvoiceModal;

import React from 'react';
import { CartItem } from '../types';

interface CartProps {
  isOpen: boolean;
  onClose: () => void;
  items: CartItem[];
  onUpdateQuantity: (id: string, delta: number) => void;
  onCheckout: () => void;
}

const Cart: React.FC<CartProps> = ({ isOpen, onClose, items, onUpdateQuantity, onCheckout }) => {
  const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex justify-end">
      <div 
        className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm"
        onClick={onClose}
      ></div>
      <div className="relative w-full max-w-md bg-white h-full flex flex-col shadow-2xl animate-in slide-in-from-right duration-300">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <i className="fas fa-shopping-bag text-indigo-600"></i>
            Your Order
          </h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <i className="fas fa-times text-slate-400"></i>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {items.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400">
              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                <i className="fas fa-utensils text-3xl"></i>
              </div>
              <p className="font-medium">Your cart is empty</p>
              <button 
                onClick={onClose}
                className="mt-4 text-indigo-600 font-semibold hover:underline"
              >
                Go back to menu
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              {items.map((item) => (
                <div key={item.id} className="flex gap-4">
                  <div className="w-20 h-20 rounded-xl overflow-hidden shrink-0 border border-slate-100">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
                  </div>
                  <div className="flex-1">
                    <h4 className="font-bold text-slate-800 text-sm mb-1">{item.name}</h4>
                    <p className="text-indigo-600 font-bold text-sm mb-3">${(item.price * item.quantity).toFixed(2)}</p>
                    <div className="flex items-center gap-3">
                      <button 
                        onClick={() => onUpdateQuantity(item.id, -1)}
                        className="w-8 h-8 rounded-lg bg-slate-50 border border-slate-200 flex items-center justify-center text-slate-600 hover:bg-indigo-600 hover:text-white transition-all"
                      >
                        <i className="fas fa-minus text-xs"></i>
                      </button>
                      <span className="font-bold text-slate-800">{item.quantity}</span>
                      <button 
                        onClick={() => onUpdateQuantity(item.id, 1)}
                        className="w-8 h-8 rounded-lg bg-slate-50 border border-slate-200 flex items-center justify-center text-slate-600 hover:bg-indigo-600 hover:text-white transition-all"
                      >
                        <i className="fas fa-plus text-xs"></i>
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {items.length > 0 && (
          <div className="p-6 bg-slate-50 border-t border-slate-200">
            <div className="flex justify-between items-center mb-6">
              <span className="text-slate-500 font-medium">Subtotal</span>
              <span className="text-2xl font-black text-slate-900">${total.toFixed(2)}</span>
            </div>
            <button 
              onClick={onCheckout}
              className="w-full py-4 bg-indigo-600 text-white font-bold rounded-2xl hover:bg-indigo-700 transition-colors shadow-xl shadow-indigo-100 flex items-center justify-center gap-3"
            >
              Confirm & Generate Invoice
              <i className="fas fa-arrow-right"></i>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Cart;

import React, { useState, useEffect, useCallback } from 'react';
import { FoodItem, Category, CartItem } from './types';
import { INITIAL_FOOD_ITEMS } from './constants';
import { generateAppetizingMenu } from './services/geminiService';
import Header from './components/Header';
import CategoryFilter from './components/CategoryFilter';
import FoodCard from './components/FoodCard';
import Cart from './components/Cart';
import InvoiceModal from './components/InvoiceModal';

const App: React.FC = () => {
  const [foodItems, setFoodItems] = useState<FoodItem[]>(INITIAL_FOOD_ITEMS);
  const [activeCategory, setActiveCategory] = useState<Category>(Category.All);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isInvoiceOpen, setIsInvoiceOpen] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);

  // Filter logic
  const filteredItems = foodItems.filter(item => 
    activeCategory === Category.All || item.category === activeCategory
  );

  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1 }];
    });
    // Visual feedback
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-4 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-6 py-3 rounded-full shadow-2xl z-[100] animate-in fade-in slide-in-from-bottom duration-300';
    toast.textContent = `Added ${item.name} to order`;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.classList.add('animate-out', 'fade-out', 'slide-out-to-bottom');
      setTimeout(() => toast.remove(), 300);
    }, 2000);
  };

  const updateCartQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = Math.max(0, item.quantity + delta);
          return { ...item, quantity: newQty };
        }
        return item;
      }).filter(item => item.quantity > 0);
    });
  };

  const enhanceMenu = async () => {
    if (isEnhancing) return;
    setIsEnhancing(true);
    const enhanced = await generateAppetizingMenu(JSON.stringify(foodItems));
    if (enhanced) {
      setFoodItems(enhanced);
    }
    setIsEnhancing(false);
  };

  const handleCheckout = () => {
    setIsCartOpen(false);
    setIsInvoiceOpen(true);
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-0">
      <Header 
        cartCount={cart.reduce((sum, item) => sum + item.quantity, 0)} 
        onCartClick={() => setIsCartOpen(true)} 
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Hero Section */}
        <section className="relative rounded-[2.5rem] bg-indigo-600 p-8 md:p-12 mb-12 overflow-hidden">
          <div className="relative z-10 max-w-2xl">
            <span className="inline-block px-4 py-1.5 rounded-full bg-white/20 text-white text-sm font-semibold mb-6 backdrop-blur-sm">
              ✨ Experience Premium Dining
            </span>
            <h1 className="text-4xl md:text-5xl font-black text-white mb-6 leading-tight">
              Delicious Food, Delivered <br/>to Your <span className="text-indigo-200">Table.</span>
            </h1>
            <p className="text-indigo-100 text-lg mb-8 max-w-lg">
              Explore our curated selection of fine dishes, crafted with the freshest seasonal ingredients.
            </p>
            <div className="flex flex-wrap gap-4">
              <button 
                onClick={() => {
                  const el = document.getElementById('menu-section');
                  el?.scrollIntoView({ behavior: 'smooth' });
                }}
                className="px-8 py-3.5 bg-white text-indigo-600 rounded-2xl font-bold hover:bg-slate-50 transition-all shadow-xl"
              >
                Browse Menu
              </button>
              <button 
                onClick={enhanceMenu}
                disabled={isEnhancing}
                className="px-8 py-3.5 bg-indigo-500 text-white rounded-2xl font-bold hover:bg-indigo-400 border border-indigo-400 transition-all flex items-center gap-2"
              >
                {isEnhancing ? (
                  <i className="fas fa-spinner fa-spin"></i>
                ) : (
                  <i className="fas fa-magic"></i>
                )}
                Enhance Descriptions (AI)
              </button>
            </div>
          </div>

          {/* Decorative shapes */}
          <div className="absolute top-0 right-0 w-1/2 h-full hidden lg:block">
            <div className="absolute top-10 right-10 w-64 h-64 bg-indigo-500 rounded-full blur-3xl opacity-50"></div>
            <div className="absolute bottom-10 right-40 w-48 h-48 bg-violet-400 rounded-full blur-2xl opacity-40"></div>
            <img 
              src="https://images.unsplash.com/photo-1504674900247-0877df9cc836?q=80&w=1000&auto=format&fit=crop" 
              className="absolute right-0 top-1/2 -translate-y-1/2 w-[450px] h-[350px] object-cover rounded-[3rem] shadow-2xl rotate-3"
              alt="Hero Food"
            />
          </div>
        </section>

        {/* Menu Section */}
        <section id="menu-section">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">Our Collection</h2>
            <CategoryFilter 
              activeCategory={activeCategory} 
              onCategoryChange={setActiveCategory} 
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredItems.map(item => (
              <FoodCard 
                key={item.id} 
                item={item} 
                onAddToCart={addToCart} 
              />
            ))}
          </div>

          {filteredItems.length === 0 && (
            <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-slate-300">
              <i className="fas fa-search text-4xl text-slate-300 mb-4"></i>
              <p className="text-slate-500 font-medium">No items found in this category.</p>
            </div>
          )}
        </section>
      </main>

      {/* Cart Drawer */}
      <Cart 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart} 
        onUpdateQuantity={updateCartQuantity}
        onCheckout={handleCheckout}
      />

      {/* Invoice Modal */}
      {isInvoiceOpen && (
        <InvoiceModal 
          cart={cart} 
          onClose={() => setIsInvoiceOpen(false)} 
          onClearCart={() => setCart([])}
        />
      )}

      {/* Mobile Floating Cart Button */}
      {cart.length > 0 && !isCartOpen && (
        <div className="fixed bottom-6 right-6 lg:hidden z-30">
          <button 
            onClick={() => setIsCartOpen(true)}
            className="w-16 h-16 bg-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white text-2xl animate-bounce"
          >
            <i className="fas fa-shopping-bag"></i>
          </button>
        </div>
      )}

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 mt-20">
        <div className="max-w-7xl mx-auto px-4 py-12 text-center">
          <div className="flex items-center justify-center gap-2 mb-4">
             <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-xs">
              <i className="fas fa-utensils"></i>
            </div>
            <span className="font-bold text-slate-800">BistroCloud</span>
          </div>
          <p className="text-slate-500 text-sm">© 2024 BistroCloud. Powered by Gemini Pro.</p>
        </div>
      </footer>
    </div>
  );
};

