import React, { useState } from 'react';
import { CartItem, CustomerRecord } from '../types';

interface InvoiceModalProps {
  cart: CartItem[];
  onClose: () => void;
  onClearCart: () => void;
  onRecordSaved: (record: CustomerRecord) => void;
}

const InvoiceModal: React.FC<InvoiceModalProps> = ({ cart, onClose, onClearCart, onRecordSaved }) => {
  const [customerName, setCustomerName] = useState('');
  const [customerContact, setCustomerContact] = useState('');
  const [isGenerated, setIsGenerated] = useState(false);

  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const orderId = Math.random().toString(36).substring(2, 9).toUpperCase();
  const date = new Date().toLocaleString('en-US', { 
    year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' 
  });

  const handleGenerate = (e: React.FormEvent) => {
    e.preventDefault();
    if (customerName.trim() && customerContact.trim()) {
      setIsGenerated(true);

      // Save record to history
      const record: CustomerRecord = {
        id: orderId,
        name: customerName,
        contact: customerContact,
        total: total,
        timestamp: date,
        items: cart.map(i => `${i.name} (x${i.quantity})`).join(', ')
      };
      onRecordSaved(record);
    }
  };

  const getInvoiceText = () => {
    let text = `*BistroCloud Invoice - #${orderId}*\n`;
    text += `Customer: ${customerName}\n`;
    text += `Date: ${date}\n`;
    text += `--------------------------\n`;
    cart.forEach(item => {
      text += `${item.name} x${item.quantity} - $${(item.price * item.quantity).toFixed(2)}\n`;
    });
    text += `--------------------------\n`;
    text += `*Total: $${total.toFixed(2)}*\n\n`;
    text += `Thank you for dining with us!`;
    return encodeURIComponent(text);
  };

  const shareWhatsApp = () => {
    window.open(`https://wa.me/${customerContact.replace(/\D/g,'')}?text=${getInvoiceText()}`, '_blank');
  };

  const shareSMS = () => {
    window.location.href = `sms:${customerContact}?body=${getInvoiceText()}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <div className="bg-white w-full max-w-md rounded-[2rem] overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-300">
        {!isGenerated ? (
          <div className="p-10">
            <h2 className="text-3xl font-black text-slate-800 mb-2">Final Step</h2>
            <p className="text-slate-500 mb-8">We need some details to generate your digital receipt.</p>
            <form onSubmit={handleGenerate} className="space-y-6">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Customer Name</label>
                <input
                  type="text"
                  required
                  value={customerName}
                  onChange={(e) => setCustomerName(e.target.value)}
                  placeholder="e.g. John Doe"
                  className="w-full px-5 py-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Contact Number</label>
                <input
                  type="tel"
                  required
                  value={customerContact}
                  onChange={(e) => setCustomerContact(e.target.value)}
                  placeholder="e.g. +1 234 567 890"
                  className="w-full px-5 py-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                />
              </div>
              <div className="flex gap-4 pt-4">
                <button 
                  type="button"
                  onClick={onClose}
                  className="flex-1 py-4 font-bold text-slate-500 hover:bg-slate-50 rounded-2xl transition-colors"
                >
                  Back
                </button>
                <button 
                  type="submit"
                  className="flex-2 px-8 py-4 bg-indigo-600 text-white font-bold rounded-2xl hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100"
                >
                  Generate
                </button>
              </div>
            </form>
          </div>
        ) : (
          <div className="max-h-[90vh] flex flex-col">
            <div className="p-8 overflow-y-auto flex-1">
              <div className="flex justify-between items-start mb-8">
                <div className="w-14 h-14 bg-indigo-600 rounded-[1.25rem] flex items-center justify-center text-white text-xl">
                  <i className="fas fa-receipt"></i>
                </div>
                <div className="text-right">
                  <h2 className="text-xl font-black text-slate-900 leading-none mb-1 uppercase italic tracking-tighter">Receipt</h2>
                  <p className="text-xs font-bold text-indigo-600">ID: {orderId}</p>
                </div>
              </div>

              <div className="space-y-1 mb-8">
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Billed To</p>
                <p className="font-bold text-slate-800 text-lg">{customerName}</p>
                <p className="text-xs text-slate-500">{customerContact}</p>
                <p className="text-[10px] text-slate-400 mt-2">{date}</p>
              </div>

              <div className="border-y border-dashed border-slate-200 py-6 mb-6">
                <table className="w-full text-sm">
                  <tbody className="text-slate-800">
                    {cart.map((item) => (
                      <tr key={item.id}>
                        <td className="py-2 pr-4">
                          <p className="font-bold">{item.name}</p>
                          <p className="text-xs text-slate-400">Qty: {item.quantity}</p>
                        </td>
                        <td className="py-2 text-right font-medium text-slate-600 tracking-tight">
                          ${(item.price * item.quantity).toFixed(2)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="flex justify-between items-center bg-slate-50 p-6 rounded-2xl mb-2">
                <span className="text-slate-500 font-bold text-sm uppercase">Total Amount</span>
                <span className="text-2xl font-black text-indigo-600 tracking-tighter">${total.toFixed(2)}</span>
              </div>
            </div>

            <div className="p-8 bg-white border-t border-slate-100">
              <div className="grid grid-cols-2 gap-4 mb-4">
                <button 
                  onClick={shareWhatsApp}
                  className="flex flex-col items-center justify-center gap-2 py-4 bg-[#25D366]/10 text-[#25D366] rounded-2xl font-bold hover:bg-[#25D366]/20 transition-all border border-[#25D366]/30"
                >
                  <i className="fab fa-whatsapp text-2xl"></i>
                  <span className="text-xs">WhatsApp</span>
                </button>
                <button 
                  onClick={shareSMS}
                  className="flex flex-col items-center justify-center gap-2 py-4 bg-slate-900 text-white rounded-2xl font-bold hover:bg-slate-800 transition-all shadow-xl shadow-slate-200"
                >
                  <i className="fas fa-comment-dots text-2xl"></i>
                  <span className="text-xs">Direct SMS</span>
                </button>
              </div>
              <button 
                onClick={() => {
                  onClearCart();
                  onClose();
                }}
                className="w-full py-4 text-slate-400 font-bold text-sm hover:text-slate-600 transition-colors uppercase tracking-widest"
              >
                Done • Next Order
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

