import React, { useState, useEffect, useCallback } from 'react';
import { FoodItem, Category, CartItem, CustomerRecord } from './types';
import { INITIAL_FOOD_ITEMS } from './constants';
import { generateAppetizingMenu } from './services/geminiService';
import Header from './components/Header';
import CategoryFilter from './components/CategoryFilter';
import FoodCard from './components/FoodCard';
import Cart from './components/Cart';
import InvoiceModal from './components/InvoiceModal';
import AdminDashboard from './components/AdminDashboard';
import FoodFormModal from './components/FoodFormModal';

const App: React.FC = () => {
  // Persistence logic (optional enhancement but good for demo)
  const [foodItems, setFoodItems] = useState<FoodItem[]>(() => {
    const saved = localStorage.getItem('bistro_menu');
    return saved ? JSON.parse(saved) : INITIAL_FOOD_ITEMS;
  });

  const [customerHistory, setCustomerHistory] = useState<CustomerRecord[]>(() => {
    const saved = localStorage.getItem('bistro_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeCategory, setActiveCategory] = useState<Category>(Category.All);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  // UI states
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isInvoiceOpen, setIsInvoiceOpen] = useState(false);
  const [isAdminView, setIsAdminView] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);

  // Form states
  const [isFoodModalOpen, setIsFoodModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);

  // Sync to local storage
  useEffect(() => {
    localStorage.setItem('bistro_menu', JSON.stringify(foodItems));
  }, [foodItems]);

  useEffect(() => {
    localStorage.setItem('bistro_history', JSON.stringify(customerHistory));
  }, [customerHistory]);

  // Search and Filter logic
  const filteredItems = foodItems.filter(item => {
    const matchesCategory = activeCategory === Category.All || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const addToCart = (item: FoodItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1 }];
    });

    // Simple visual feedback
    showToast(`Added ${item.name} to order`);
  };

  const showToast = (msg: string) => {
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-[1.25rem] shadow-2xl z-[100] font-bold animate-in fade-in slide-in-from-bottom-4 duration-300';
    toast.textContent = msg;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.classList.replace('animate-in', 'animate-out');
      toast.classList.add('fade-out', 'slide-out-to-bottom-4');
      setTimeout(() => toast.remove(), 300);
    }, 2000);
  };

  const updateCartQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        return { ...item, quantity: Math.max(0, item.quantity + delta) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const saveFoodItem = (item: FoodItem) => {
    if (editingItem) {
      setFoodItems(prev => prev.map(i => i.id === item.id ? item : i));
      showToast('Item updated successfully');
    } else {
      setFoodItems(prev => [item, ...prev]);
      showToast('New item added to menu');
    }
    setIsFoodModalOpen(false);
    setEditingItem(null);
  };

  const deleteFoodItem = (id: string) => {
    if (confirm('Are you sure you want to remove this item?')) {
      setFoodItems(prev => prev.filter(i => i.id !== id));
      showToast('Item deleted');
    }
  };

  const enhanceMenu = async () => {
    if (isEnhancing) return;
    setIsEnhancing(true);
    const enhanced = await generateAppetizingMenu(JSON.stringify(foodItems));
    if (enhanced) {
      setFoodItems(enhanced);
      showToast('AI Enhanced your menu!');
    }
    setIsEnhancing(false);
  };

  const handleRecordSaved = (record: CustomerRecord) => {
    setCustomerHistory(prev => [record, ...prev]);
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-slate-50/50">
      <Header 
        cartCount={cart.reduce((sum, item) => sum + item.quantity, 0)} 
        onCartClick={() => setIsCartOpen(true)}
        isAdmin={isAdminView}
        onToggleAdmin={() => setIsAdminView(!isAdminView)}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-12">
        {isAdminView ? (
          <AdminDashboard 
            items={foodItems}
            history={customerHistory}
            onAddItem={() => { setEditingItem(null); setIsFoodModalOpen(true); }}
            onEditItem={(item) => { setEditingItem(item); setIsFoodModalOpen(true); }}
            onDeleteItem={deleteFoodItem}
          />
        ) : (
          <>
            {/* Hero Section */}
            <section className="relative rounded-[3rem] bg-indigo-600 p-8 md:p-16 mb-16 overflow-hidden">
              <div className="relative z-10 max-w-2xl">
                <div className="flex items-center gap-2 px-4 py-2 rounded-full bg-white/10 backdrop-blur-md text-white/90 text-sm font-bold mb-8 w-fit border border-white/10">
                  <span className="flex h-2 w-2 rounded-full bg-green-400 animate-pulse"></span>
                  OPEN FOR DINING
                </div>
                <h1 className="text-4xl md:text-6xl font-black text-white mb-8 leading-[1.1] tracking-tighter">
                  Crafting Moments <br/>Through <span className="text-indigo-200">Exquisite Food.</span>
                </h1>
                <div className="flex flex-wrap gap-4">
                  <button 
                    onClick={() => document.getElementById('menu-section')?.scrollIntoView({ behavior: 'smooth' })}
                    className="px-8 py-4 bg-white text-indigo-600 rounded-2xl font-black hover:scale-105 transition-all shadow-2xl shadow-indigo-900/20 active:scale-95"
                  >
                    View Menu
                  </button>
                  <button 
                    onClick={enhanceMenu}
                    disabled={isEnhancing}
                    className="px-8 py-4 bg-indigo-500/30 text-white rounded-2xl font-black hover:bg-indigo-500/50 border border-white/20 transition-all flex items-center gap-2 active:scale-95"
                  >
                    {isEnhancing ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-wand-magic-sparkles"></i>}
                    AI Content Boost
                  </button>
                </div>
              </div>

              <div className="absolute top-0 right-0 w-1/2 h-full hidden lg:block">
                <div className="absolute top-0 right-0 w-full h-full bg-gradient-to-l from-indigo-600/50 to-transparent"></div>
                <img 
                  src="https://images.unsplash.com/photo-1559339352-11d035aa65de?q=80&w=1000&auto=format&fit=crop" 
                  className="absolute right-[-10%] top-1/2 -translate-y-1/2 w-[120%] h-[120%] object-cover opacity-60 mix-blend-overlay rotate-3 scale-110"
                  alt="Fine Dining"
                />
              </div>
            </section>

            {/* Menu Section */}
            <section id="menu-section">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
                <div>
                  <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase italic">Our Specialties</h2>
                  <p className="text-slate-500 font-medium">Handpicked flavors from our master chefs.</p>
                </div>
                <CategoryFilter 
                  activeCategory={activeCategory} 
                  onCategoryChange={setActiveCategory} 
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                {filteredItems.map(item => (
                  <FoodCard 
                    key={item.id} 
                    item={item} 
                    onAddToCart={addToCart} 
                  />
                ))}
              </div>

              {filteredItems.length === 0 && (
                <div className="text-center py-32 bg-white rounded-[3rem] border border-dashed border-slate-200">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6">
                    <i className="fas fa-search text-3xl text-slate-300"></i>
                  </div>
                  <h3 className="text-xl font-bold text-slate-800 mb-2">No dishes found</h3>
                  <p className="text-slate-500 max-w-xs mx-auto">Try searching for something else or browse another category.</p>
                </div>
              )}
            </section>
          </>
        )}
      </main>

      {/* Cart, Modals, etc. */}
      <Cart 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart} 
        onUpdateQuantity={updateCartQuantity}
        onCheckout={() => { setIsCartOpen(false); setIsInvoiceOpen(true); }}
      />

      {isInvoiceOpen && (
        <InvoiceModal 
          cart={cart} 
          onClose={() => setIsInvoiceOpen(false)} 
          onClearCart={() => setCart([])}
          onRecordSaved={handleRecordSaved}
        />
      )}

      {isFoodModalOpen && (
        <FoodFormModal 
          item={editingItem} 
          onClose={() => setIsFoodModalOpen(false)} 
          onSave={saveFoodItem}
        />
      )}

      {/* Floating Action Button (Mobile only) */}
      {!isAdminView && cart.length > 0 && !isCartOpen && (
        <div className="fixed bottom-8 right-8 lg:hidden z-30">
          <button 
            onClick={() => setIsCartOpen(true)}
            className="w-16 h-16 bg-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white text-2xl hover:scale-110 active:scale-90 transition-all"
          >
            <i className="fas fa-shopping-bag"></i>
          </button>
        </div>
      )}
    </div>
  );
};

