import React, { useState, useEffect, useCallback } from 'react';
import { FoodItem, Category, CartItem, CustomerRecord } from './types';
import { INITIAL_FOOD_ITEMS } from './constants';
import { generateAppetizingMenu } from './services/geminiService';
import Header from './components/Header';
import CategoryFilter from './components/CategoryFilter';
import FoodCard from './components/FoodCard';
import Cart from './components/Cart';
import InvoiceModal from './components/InvoiceModal';
import AdminDashboard from './components/AdminDashboard';
import FoodFormModal from './components/FoodFormModal';

const App: React.FC = () => {
  const [foodItems, setFoodItems] = useState<FoodItem[]>(() => {
    const saved = localStorage.getItem('bistro_menu');
    return saved ? JSON.parse(saved) : INITIAL_FOOD_ITEMS;
  });

  const [customerHistory, setCustomerHistory] = useState<CustomerRecord[]>(() => {
    const saved = localStorage.getItem('bistro_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeCategory, setActiveCategory] = useState<Category>(Category.All);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isInvoiceOpen, setIsInvoiceOpen] = useState(false);
  const [isAdminView, setIsAdminView] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);

  const [isFoodModalOpen, setIsFoodModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);

  useEffect(() => {
    localStorage.setItem('bistro_menu', JSON.stringify(foodItems));
  }, [foodItems]);

  useEffect(() => {
    localStorage.setItem('bistro_history', JSON.stringify(customerHistory));
  }, [customerHistory]);

  const filteredItems = foodItems.filter(item => {
    const matchesCategory = activeCategory === Category.All || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const addToCart = (item: FoodItem, size: 'Half' | 'Full') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.selectedSize === size);
      if (existing) {
        return prev.map(i => (i.id === item.id && i.selectedSize === size) ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1, selectedSize: size }];
    });

    showToast(`Added ${item.name} (${size}) to bag! 😋`);
  };

  const showToast = (msg: string) => {
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl z-[100] font-bold animate-in fade-in slide-in-from-bottom-4 duration-300';
    toast.textContent = msg;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.classList.replace('animate-in', 'animate-out');
      toast.classList.add('fade-out', 'slide-out-to-bottom-4');
      setTimeout(() => toast.remove(), 300);
    }, 2000);
  };

  const updateCartQuantity = (id: string, delta: number, size: 'Half' | 'Full') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        return { ...item, quantity: Math.max(0, item.quantity + delta) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const saveFoodItem = (item: FoodItem) => {
    if (editingItem) {
      setFoodItems(prev => prev.map(i => i.id === item.id ? item : i));
      showToast('Dish updated successfully! ✨');
    } else {
      setFoodItems(prev => [item, ...prev]);
      showToast('New dish added to menu! ➕');
    }
    setIsFoodModalOpen(false);
    setEditingItem(null);
  };

  const deleteFoodItem = (id: string) => {
    if (confirm('Are you sure you want to remove this dish?')) {
      setFoodItems(prev => prev.filter(i => i.id !== id));
      showToast('Dish removed! 🗑️');
    }
  };

  const enhanceMenu = async () => {
    if (isEnhancing) return;
    setIsEnhancing(true);
    const enhanced = await generateAppetizingMenu(JSON.stringify(foodItems));
    if (enhanced) {
      setFoodItems(enhanced);
      showToast('Menu magically enhanced! ✨');
    }
    setIsEnhancing(false);
  };

  const handleRecordSaved = (record: CustomerRecord) => {
    setCustomerHistory(prev => [record, ...prev]);
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-slate-50/50">
      <Header 
        cartCount={cart.reduce((sum, item) => sum + item.quantity, 0)} 
        onCartClick={() => setIsCartOpen(true)}
        isAdmin={isAdminView}
        onToggleAdmin={() => setIsAdminView(!isAdminView)}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-16">
        {isAdminView ? (
          <AdminDashboard 
            items={foodItems}
            history={customerHistory}
            onAddItem={() => { setEditingItem(null); setIsFoodModalOpen(true); }}
            onEditItem={(item) => { setEditingItem(item); setIsFoodModalOpen(true); }}
            onDeleteItem={deleteFoodItem}
          />
        ) : (
          <>
            <section className="relative rounded-[3.5rem] bg-indigo-600 p-10 md:p-20 mb-20 overflow-hidden shadow-2xl shadow-indigo-100">
              <div className="relative z-10 max-w-2xl">
                <div className="flex items-center gap-3 px-5 py-2.5 rounded-full bg-white/10 backdrop-blur-md text-white text-xs font-black mb-10 w-fit border border-white/20 uppercase tracking-[0.2em]">
                  <span className="flex h-2 w-2 rounded-full bg-green-400 animate-pulse"></span>
                  Fresh & Hot Now
                </div>
                <h1 className="text-5xl md:text-7xl font-black text-white mb-10 leading-[1] tracking-tighter italic">
                  Gourmet Bites, <br/>Delivered <span className="text-indigo-200">Fast.</span>
                </h1>
                <div className="flex flex-wrap gap-5">
                  <button 
                    onClick={() => document.getElementById('menu-section')?.scrollIntoView({ behavior: 'smooth' })}
                    className="px-10 py-5 bg-white text-indigo-600 rounded-[2rem] font-black hover:scale-105 transition-all shadow-xl active:scale-95 text-lg"
                  >
                    View Menu 😋
                  </button>
                  <button 
                    onClick={enhanceMenu}
                    disabled={isEnhancing}
                    className="px-10 py-5 bg-indigo-500/30 text-white rounded-[2rem] font-black hover:bg-indigo-500/50 border border-white/20 transition-all flex items-center gap-3 active:scale-95"
                  >
                    {isEnhancing ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-wand-magic-sparkles"></i>}
                    AI Magic Boost
                  </button>
                </div>
              </div>

              <div className="absolute top-0 right-0 w-1/2 h-full hidden lg:block pointer-events-none">
                <img 
                  src="https://images.unsplash.com/photo-1514326640560-7d063ef2aed5?q=80&w=1000&auto=format&fit=crop" 
                  className="absolute right-[-15%] top-1/2 -translate-y-1/2 w-[110%] h-[120%] object-cover opacity-50 mix-blend-overlay rotate-2"
                  alt="Food"
                />
              </div>
            </section>

            <section id="menu-section">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 mb-16">
                <div>
                  <h2 className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">Today's Selection</h2>
                  <p className="text-slate-500 font-bold mt-2">Premium quality ingredients, cooked with love. ❤️</p>
                </div>
                <CategoryFilter 
                  activeCategory={activeCategory} 
                  onCategoryChange={setActiveCategory} 
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-10">
                {filteredItems.map(item => (
                  <FoodCard 
                    key={item.id} 
                    item={item} 
                    onAddToCart={addToCart} 
                  />
                ))}
              </div>

              {filteredItems.length === 0 && (
                <div className="text-center py-40 bg-white rounded-[4rem] border border-dashed border-slate-200">
                  <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-8">
                    <i className="fas fa-search text-4xl text-slate-200"></i>
                  </div>
                  <h3 className="text-2xl font-black text-slate-800 mb-3">Hmm, no matches!</h3>
                  <p className="text-slate-500 max-w-xs mx-auto font-medium">Try searching for something else or browse different categories!</p>
                </div>
              )}
            </section>
          </>
        )}
      </main>

      <Cart 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart} 
        onUpdateQuantity={updateCartQuantity}
        onCheckout={() => { setIsCartOpen(false); setIsInvoiceOpen(true); }}
      />

      {isInvoiceOpen && (
        <InvoiceModal 
          cart={cart} 
          onClose={() => setIsInvoiceOpen(false)} 
          onClearCart={() => setCart([])}
          onRecordSaved={handleRecordSaved}
        />
      )}

      {isFoodModalOpen && (
        <FoodFormModal 
          item={editingItem} 
          onClose={() => setIsFoodModalOpen(false)} 
          onSave={saveFoodItem}
        />
      )}

      {!isAdminView && cart.length > 0 && !isCartOpen && (
        <div className="fixed bottom-10 right-10 lg:hidden z-30">
          <button 
            onClick={() => setIsCartOpen(true)}
            className="w-20 h-20 bg-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white text-3xl hover:scale-110 active:scale-90 transition-all border-4 border-white"
          >
            <i className="fas fa-shopping-bag"></i>
          </button>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { FoodItem, Category } from '../types';

interface FoodFormModalProps {
  item?: FoodItem | null;
  onClose: () => void;
  onSave: (item: FoodItem) => void;
}

const FoodFormModal: React.FC<FoodFormModalProps> = ({ item, onClose, onSave }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [formData, setFormData] = useState<Partial<FoodItem>>({
    name: '',
    description: '',
    price: 0,
    halfPrice: undefined,
    category: Category.Starters,
    image: 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?q=80&w=1000&auto=format&fit=crop'
  });

  const [isUploading, setIsUploading] = useState(false);

  useEffect(() => {
    if (item) setFormData(item);
  }, [item]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsUploading(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, image: reader.result as string });
        setIsUploading(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      id: item?.id || Math.random().toString(36).substr(2, 9),
    } as FoodItem);
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <div className="bg-white w-full max-w-xl rounded-[2.5rem] overflow-hidden shadow-2xl animate-in zoom-in duration-200">
        <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
          <div>
            <h2 className="text-2xl font-black text-slate-800">
              {item ? '📝 Update Dish' : '➕ Create New Dish'}
            </h2>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Menu Management</p>
          </div>
          <button onClick={onClose} className="w-10 h-10 hover:bg-slate-100 rounded-full flex items-center justify-center transition-colors">
            <i className="fas fa-times text-slate-400"></i>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 max-h-[75vh] overflow-y-auto space-y-6">
          {/* Image Section */}
          <div className="space-y-3">
            <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest">Dish Presentation</label>
            <div className="flex items-center gap-6">
              <div className="relative w-32 h-32 rounded-3xl overflow-hidden border-2 border-slate-100 group shadow-sm bg-slate-50">
                <img src={formData.image} className="w-full h-full object-cover" alt="Preview" />
                {isUploading && (
                  <div className="absolute inset-0 bg-white/80 backdrop-blur flex items-center justify-center">
                    <i className="fas fa-circle-notch fa-spin text-indigo-600"></i>
                  </div>
                )}
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center text-white text-xs font-bold gap-1"
                >
                  <i className="fas fa-camera text-lg"></i>
                  Change
                </button>
              </div>
              <div className="flex-1 space-y-3">
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileChange} 
                  accept="image/*" 
                  className="hidden" 
                />
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full py-3 px-4 bg-white border border-slate-200 rounded-2xl text-sm font-bold text-slate-700 hover:border-indigo-600 hover:text-indigo-600 transition-all flex items-center justify-center gap-2"
                >
                  <i className="fas fa-upload text-xs"></i>
                  Upload from Device
                </button>
                <div className="relative">
                   <input 
                    className="w-full px-4 py-3 bg-slate-50 rounded-2xl border border-slate-200 text-xs focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                    placeholder="Or paste image URL here..."
                    value={formData.image?.startsWith('data:') ? '' : formData.image}
                    onChange={e => setFormData({...formData, image: e.target.value})}
                  />
                  <i className="fas fa-link absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 text-xs"></i>
                </div>
              </div>
            </div>
          </div>

          <div className="space-y-3">
            <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest">Dish Information</label>
            <input 
              required
              placeholder="Dish Name (e.g. Spicy Paneer Tikka)"
              className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none font-bold text-slate-800"
              value={formData.name}
              onChange={e => setFormData({...formData, name: e.target.value})}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Full Plate (₹)</label>
              <input 
                required
                type="number"
                placeholder="0.00"
                className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none font-black text-indigo-600"
                value={formData.price}
                onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
              />
            </div>
            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-1">Half Plate (₹)</label>
              <input 
                type="number"
                placeholder="Optional"
                className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none font-bold text-slate-600"
                value={formData.halfPrice || ''}
                onChange={e => setFormData({...formData, halfPrice: e.target.value ? parseFloat(e.target.value) : undefined})}
              />
            </div>
          </div>

          <div className="space-y-3">
             <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest">Menu Category</label>
            <select 
              className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none font-bold text-slate-700 appearance-none cursor-pointer"
              value={formData.category}
              onChange={e => setFormData({...formData, category: e.target.value})}
            >
              {Object.values(Category).filter(c => c !== Category.All).map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
          </div>

          <div className="space-y-3">
            <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest">Appetizing Description</label>
            <textarea 
              rows={2}
              placeholder="Describe the flavors, ingredients, and texture..."
              className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none text-sm text-slate-600"
              value={formData.description}
              onChange={e => setFormData({...formData, description: e.target.value})}
            />
          </div>

          <div className="pt-6 flex gap-4">
            <button 
              type="button"
              onClick={onClose}
              className="flex-1 py-4 font-bold text-slate-500 hover:bg-slate-50 rounded-2xl transition-all"
            >
              Cancel
            </button>
            <button 
              type="submit"
              disabled={isUploading}
              className="flex-[2] py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 disabled:opacity-50"
            >
              {item ? 'Save Changes ✨' : 'Add to Menu 🚀'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

