import React, { useState } from 'react';
import { CartItem, CustomerRecord } from '../types';

interface InvoiceModalProps {
  cart: CartItem[];
  onClose: () => void;
  onClearCart: () => void;
  onRecordSaved: (record: CustomerRecord) => void;
}

const InvoiceModal: React.FC<InvoiceModalProps> = ({ cart, onClose, onClearCart, onRecordSaved }) => {
  const [customerName, setCustomerName] = useState('');
  const [customerContact, setCustomerContact] = useState('');
  const [isGenerated, setIsGenerated] = useState(false);

  const subtotal = cart.reduce((sum, item) => {
    const unitPrice = item.selectedSize === 'Half' && item.halfPrice ? item.halfPrice : item.price;
    return sum + unitPrice * item.quantity;
  }, 0);

  const taxRate = 0.10; // 10% Tax as requested
  const taxAmount = subtotal * taxRate;
  const total = subtotal + taxAmount;

  const orderId = Math.random().toString(36).substring(2, 9).toUpperCase();
  const date = new Date().toLocaleString('en-IN', { 
    year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' 
  });

  const handleGenerate = (e: React.FormEvent) => {
    e.preventDefault();
    if (customerName.trim() && customerContact.trim()) {
      setIsGenerated(true);

      const record: CustomerRecord = {
        id: `INV-${orderId}`,
        name: customerName,
        contact: customerContact,
        total: total,
        timestamp: date,
        items: cart.map(i => `${i.name} (${i.selectedSize} x${i.quantity})`).join(', ')
      };
      onRecordSaved(record);
    }
  };

  const getInvoiceText = () => {
    let text = `Hi ${customerName}! 👋\n\n`;
    text += `Thank you for your order from *BistroBill*! 🥗 Here is your receipt:\n\n`;
    text += `*Invoice:* #INV-${orderId}\n`;
    text += `--------------------------\n`;
    cart.forEach(item => {
      const p = item.selectedSize === 'Half' ? item.halfPrice : item.price;
      text += `${item.quantity}x ${item.name} (${item.selectedSize}): ₹${(p! * item.quantity).toFixed(2)}\n`;
    });
    text += `\n*Subtotal:* ₹${subtotal.toFixed(2)}\n`;
    text += `*Tax (10%):* ₹${taxAmount.toFixed(2)}\n`;
    text += `*Total: ₹${total.toFixed(2)}*\n`;
    text += `--------------------------\n\n`;
    text += `We hope you enjoy your meal! Thank you from *BistroBill*. ✨`;
    return encodeURIComponent(text);
  };

  const shareWhatsApp = () => {
    window.open(`https://wa.me/${customerContact.replace(/\D/g,'')}?text=${getInvoiceText()}`, '_blank');
  };

  const shareSMS = () => {
    window.location.href = `sms:${customerContact}?body=${getInvoiceText()}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-300">
        {!isGenerated ? (
          <div className="p-10">
            <h2 className="text-3xl font-black text-slate-800 mb-2 italic">Almost There! 🥳</h2>
            <p className="text-slate-500 mb-8">Tell us who is ordering this yummy meal!</p>
            <form onSubmit={handleGenerate} className="space-y-6">
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Customer Name</label>
                <input
                  type="text"
                  required
                  value={customerName}
                  onChange={(e) => setCustomerName(e.target.value)}
                  placeholder="Enter name"
                  className="w-full px-6 py-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">WhatsApp / Mobile</label>
                <input
                  type="tel"
                  required
                  value={customerContact}
                  onChange={(e) => setCustomerContact(e.target.value)}
                  placeholder="e.g. 9876543210"
                  className="w-full px-6 py-4 rounded-2xl border border-slate-200 focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                />
              </div>
              <div className="flex gap-4 pt-4">
                <button 
                  type="button"
                  onClick={onClose}
                  className="flex-1 py-4 font-bold text-slate-500 hover:bg-slate-50 rounded-2xl transition-colors"
                >
                  Back
                </button>
                <button 
                  type="submit"
                  className="flex-2 px-8 py-4 bg-indigo-600 text-white font-bold rounded-2xl hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100"
                >
                  Confirm! 🚀
                </button>
              </div>
            </form>
          </div>
        ) : (
          <div className="max-h-[90vh] flex flex-col">
            <div className="p-8 overflow-y-auto flex-1 bg-gradient-to-b from-indigo-50/30 to-white">
              <div className="flex justify-between items-start mb-8">
                <div className="w-16 h-16 bg-white border border-indigo-100 rounded-2xl flex items-center justify-center text-indigo-600 text-2xl shadow-sm">
                   ✨
                </div>
                <div className="text-right">
                  <h2 className="text-2xl font-black text-slate-900 leading-none mb-1 italic tracking-tighter">Receipt</h2>
                  <p className="text-xs font-bold text-indigo-600 uppercase">#INV-{orderId}</p>
                </div>
              </div>

              <div className="mb-6">
                <h3 className="text-xl font-bold text-slate-800">Hi {customerName}! 👋</h3>
                <p className="text-sm text-slate-500 mt-1">Thank you for your order from <b>BistroBill</b>! 🥗</p>
              </div>

              <div className="border-t border-dashed border-slate-200 pt-6 mb-6">
                <div className="space-y-3 mb-6">
                  {cart.map((item) => {
                    const p = item.selectedSize === 'Half' ? item.halfPrice : item.price;
                    return (
                      <div key={item.id + item.selectedSize} className="flex justify-between items-center text-sm">
                        <div className="text-slate-600">
                          <span className="font-bold text-slate-800">{item.quantity}x</span> {item.name} <span className="text-[10px] text-indigo-500 font-bold uppercase">({item.selectedSize})</span>
                        </div>
                        <div className="text-right">
                          <p className="font-bold text-slate-900">₹{(p! * item.quantity).toFixed(2)}</p>
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="border-t border-slate-100 pt-4 space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-slate-500 font-medium">Subtotal</span>
                    <span className="text-slate-800 font-bold">₹{subtotal.toFixed(2)}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-slate-500 font-medium">Tax (10%)</span>
                    <span className="text-slate-800 font-bold">₹{taxAmount.toFixed(2)}</span>
                  </div>
                </div>
              </div>

              <div className="bg-indigo-600 p-6 rounded-[2rem] text-white shadow-xl shadow-indigo-200 mb-6">
                <div className="flex justify-between items-center">
                  <span className="font-bold text-indigo-100">Total Amount ✨</span>
                  <span className="text-3xl font-black tracking-tighter text-white">₹{total.toFixed(2)}</span>
                </div>
              </div>

              <p className="text-center text-[11px] font-bold text-slate-400 italic">We hope you enjoy your meal! Thank you from BistroBill. ✨</p>
            </div>

            <div className="p-8 bg-white border-t border-slate-100">
              <div className="grid grid-cols-2 gap-4 mb-4">
                <button 
                  onClick={shareWhatsApp}
                  className="flex flex-col items-center justify-center gap-2 py-5 bg-[#25D366] text-white rounded-3xl font-black hover:opacity-90 transition-all shadow-lg shadow-green-100 active:scale-95"
                >
                  <i className="fab fa-whatsapp text-2xl"></i>
                  <span className="text-[10px] uppercase tracking-widest">WhatsApp Receipt</span>
                </button>
                <button 
                  onClick={shareSMS}
                  className="flex flex-col items-center justify-center gap-2 py-5 bg-slate-900 text-white rounded-3xl font-black hover:opacity-90 transition-all shadow-xl shadow-slate-200 active:scale-95"
                >
                  <i className="fas fa-comment-dots text-2xl"></i>
                  <span className="text-[10px] uppercase tracking-widest">Direct SMS</span>
                </button>
              </div>
              <button 
                onClick={() => {
                  onClearCart();
                  onClose();
                }}
                className="w-full py-4 text-slate-400 font-bold text-xs hover:text-indigo-600 transition-colors uppercase tracking-[0.2em]"
              >
                Close • Start Fresh ✨
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

