import React, { useState, useEffect, useCallback } from 'react';
import { FoodItem, Category, CartItem, CustomerRecord, User } from './types';
import { INITIAL_FOOD_ITEMS } from './constants';
import { generateAppetizingMenu } from './services/geminiService';
import Header from './components/Header';
import CategoryFilter from './components/CategoryFilter';
import FoodCard from './components/FoodCard';
import Cart from './components/Cart';
import InvoiceModal from './components/InvoiceModal';
import AdminDashboard from './components/AdminDashboard';
import FoodFormModal from './components/FoodFormModal';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('dhruv_user');
    return saved ? JSON.parse(saved) : null;
  });

  // Get data keys based on user ID for true account persistence
  const getMenuKey = useCallback(() => user ? `dhruv_menu_${user.id}` : 'dhruv_menu_guest', [user]);
  const getHistoryKey = useCallback(() => user ? `dhruv_history_${user.id}` : 'dhruv_history_guest', [user]);

  const [foodItems, setFoodItems] = useState<FoodItem[]>([]);
  const [customerHistory, setCustomerHistory] = useState<CustomerRecord[]>([]);

  // Initial load effect
  useEffect(() => {
    const savedMenu = localStorage.getItem(getMenuKey());
    const savedHistory = localStorage.getItem(getHistoryKey());

    setFoodItems(savedMenu ? JSON.parse(savedMenu) : INITIAL_FOOD_ITEMS);
    setCustomerHistory(savedHistory ? JSON.parse(savedHistory) : []);
  }, [getMenuKey, getHistoryKey]);

  // Persist effect
  useEffect(() => {
    if (foodItems.length > 0) {
      localStorage.setItem(getMenuKey(), JSON.stringify(foodItems));
    }
  }, [foodItems, getMenuKey]);

  useEffect(() => {
    localStorage.setItem(getHistoryKey(), JSON.stringify(customerHistory));
  }, [customerHistory, getHistoryKey]);

  useEffect(() => {
    if (user) {
      localStorage.setItem('dhruv_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('dhruv_user');
    }
  }, [user]);

  const [activeCategory, setActiveCategory] = useState<Category>(Category.All);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isInvoiceOpen, setIsInvoiceOpen] = useState(false);
  const [isAdminView, setIsAdminView] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);

  const [isFoodModalOpen, setIsFoodModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);

  const filteredItems = foodItems.filter(item => {
    const matchesCategory = activeCategory === Category.All || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const addToCart = (item: FoodItem, size: 'Half' | 'Full') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.selectedSize === size);
      if (existing) {
        return prev.map(i => (i.id === item.id && i.selectedSize === size) ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1, selectedSize: size }];
    });

    showToast(`Added ${item.name} (${size}) to bag! 😋`);
  };

  const showToast = (msg: string) => {
    const existing = document.getElementById('bistro-toast');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.id = 'bistro-toast';
    toast.className = 'fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-[2rem] shadow-2xl z-[100] font-black uppercase tracking-widest text-[10px] animate-in fade-in slide-in-from-bottom-4 duration-300 border border-white/10 backdrop-blur-xl';
    toast.textContent = msg;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.classList.replace('animate-in', 'animate-out');
      toast.classList.add('fade-out', 'slide-out-to-bottom-4');
      setTimeout(() => toast.remove(), 300);
    }, 2500);
  };

  const updateCartQuantity = (id: string, delta: number, size: 'Half' | 'Full') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        return { ...item, quantity: Math.max(0, item.quantity + delta) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const saveFoodItem = (item: FoodItem) => {
    if (editingItem) {
      setFoodItems(prev => prev.map(i => i.id === item.id ? item : i));
      showToast('Dish Refined! ✨');
    } else {
      setFoodItems(prev => [item, ...prev]);
      showToast('New Dish Launched! 🚀');
    }
    setIsFoodModalOpen(false);
    setEditingItem(null);
  };

  const deleteFoodItem = (id: string) => {
    if (confirm('Permanently remove this dish from the menu?')) {
      setFoodItems(prev => prev.filter(i => i.id !== id));
      showToast('Dish Discontinued 🗑️');
    }
  };

  const enhanceMenu = async () => {
    if (isEnhancing) return;
    setIsEnhancing(true);
    const enhanced = await generateAppetizingMenu(JSON.stringify(foodItems));
    if (enhanced) {
      setFoodItems(enhanced);
      showToast('AI Intelligence Applied! ✨');
    }
    setIsEnhancing(false);
  };

  const handleRecordSaved = (record: CustomerRecord) => {
    setCustomerHistory(prev => [record, ...prev]);
  };

  const handleLogin = (newUser: User) => {
    setUser(newUser);
    showToast(`Welcome back, ${newUser.name.split(' ')[0]}! 👋`);
  };

  const handleLogout = () => {
    setUser(null);
    setIsAdminView(false);
    showToast('Logged out successfully');
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-slate-50/50">
      <Header 
        user={user}
        onLogin={handleLogin}
        onLogout={handleLogout}
        cartCount={cart.reduce((sum, item) => sum + item.quantity, 0)} 
        onCartClick={() => setIsCartOpen(true)}
        isAdmin={isAdminView}
        onToggleAdmin={() => setIsAdminView(!isAdminView)}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-16">
        {isAdminView && user ? (
          <AdminDashboard 
            items={foodItems}
            history={customerHistory}
            onAddItem={() => { setEditingItem(null); setIsFoodModalOpen(true); }}
            onEditItem={(item) => { setEditingItem(item); setIsFoodModalOpen(true); }}
            onDeleteItem={deleteFoodItem}
          />
        ) : (
          <>
            <section className="relative rounded-[4rem] bg-indigo-600 p-10 md:p-24 mb-20 overflow-hidden shadow-[0_40px_80px_-20px_rgba(79,70,229,0.3)]">
              <div className="relative z-10 max-w-3xl">
                <div className="flex items-center gap-3 px-5 py-2.5 rounded-full bg-white/10 backdrop-blur-md text-white text-[10px] font-black mb-10 w-fit border border-white/20 uppercase tracking-[0.3em]">
                  <span className="flex h-2.5 w-2.5 rounded-full bg-green-400 animate-pulse"></span>
                  Kitchen is Live
                </div>
                <h1 className="text-6xl md:text-8xl font-black text-white mb-10 leading-[0.95] tracking-tighter italic">
                  Culinary <br/>Art, <span className="text-indigo-200">Served.</span>
                </h1>
                <div className="flex flex-wrap gap-5">
                  <button 
                    onClick={() => document.getElementById('menu-section')?.scrollIntoView({ behavior: 'smooth' })}
                    className="px-12 py-6 bg-white text-indigo-600 rounded-[2.5rem] font-black hover:scale-105 transition-all shadow-2xl active:scale-95 text-lg flex items-center gap-3"
                  >
                    Explore Menu <i className="fas fa-chevron-right text-sm"></i>
                  </button>
                  {user && (
                    <button 
                      onClick={enhanceMenu}
                      disabled={isEnhancing}
                      className="px-10 py-6 bg-white/10 text-white rounded-[2.5rem] font-black hover:bg-white/20 border border-white/20 transition-all flex items-center gap-3 active:scale-95"
                    >
                      {isEnhancing ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-magic"></i>}
                      AI Enhancement
                    </button>
                  )}
                </div>
              </div>

              <div className="absolute top-0 right-0 w-1/2 h-full hidden lg:block pointer-events-none">
                <img 
                  src="https://images.unsplash.com/photo-1555396273-367ea4eb4db5?q=80&w=1000&auto=format&fit=crop" 
                  className="absolute right-[-20%] top-1/2 -translate-y-1/2 w-[130%] h-[140%] object-cover opacity-40 mix-blend-screen rotate-6 blur-[1px]"
                  alt="Food Decor"
                />
              </div>
            </section>

            <section id="menu-section">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
                <div>
                  <h2 className="text-5xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">The Menu</h2>
                  <p className="text-slate-500 font-bold mt-4 uppercase tracking-[0.1em] text-xs">A selection of chef's daily creations.</p>
                </div>
                <CategoryFilter 
                  activeCategory={activeCategory} 
                  onCategoryChange={setActiveCategory} 
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-12">
                {filteredItems.map(item => (
                  <FoodCard 
                    key={item.id} 
                    item={item} 
                    onAddToCart={addToCart} 
                  />
                ))}
              </div>

              {filteredItems.length === 0 && (
                <div className="text-center py-48 bg-white rounded-[4rem] border border-dashed border-slate-200">
                  <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-8 text-slate-200 text-5xl">
                    <i className="fas fa-cookie-bite"></i>
                  </div>
                  <h3 className="text-2xl font-black text-slate-800 mb-3 tracking-tighter italic">Nothing Found!</h3>
                  <p className="text-slate-400 max-w-xs mx-auto font-medium text-sm">Our kitchen is creative, but we don't have that yet. Try another search!</p>
                </div>
              )}
            </section>
          </>
        )}
      </main>

      <Cart 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        items={cart} 
        onUpdateQuantity={updateCartQuantity}
        onCheckout={() => { setIsCartOpen(false); setIsInvoiceOpen(true); }}
      />

      {isInvoiceOpen && (
        <InvoiceModal 
          cart={cart} 
          onClose={() => setIsInvoiceOpen(false)} 
          onClearCart={() => setCart([])}
          onRecordSaved={handleRecordSaved}
        />
      )}

      {isFoodModalOpen && (
        <FoodFormModal 
          item={editingItem} 
          onClose={() => setIsFoodModalOpen(false)} 
          onSave={saveFoodItem}
        />
      )}

      {!isAdminView && cart.length > 0 && !isCartOpen && (
        <div className="fixed bottom-12 right-12 lg:hidden z-30">
          <button 
            onClick={() => setIsCartOpen(true)}
            className="w-20 h-20 bg-indigo-600 rounded-[2.5rem] shadow-[0_20px_40px_rgba(79,70,229,0.4)] flex items-center justify-center text-white text-3xl hover:scale-110 active:scale-90 transition-all border-4 border-white"
          >
            <i className="fas fa-shopping-basket"></i>
          </button>
        </div>
      )}
    </div>
  );
};

export default App;

