import React, { useEffect } from 'react';
import { User } from '../types';
import { jwtDecode } from 'jwt-decode';

interface HeaderProps {
  user: User | null;
  onLogin: (user: User) => void;
  onLogout: () => void;
  cartCount: number;
  onCartClick: () => void;
  isAdmin: boolean;
  onToggleAdmin: () => void;
  searchQuery: string;
  onSearchChange: (val: string) => void;
}

const Header: React.FC<HeaderProps> = ({ 
  user,
  onLogin,
  onLogout,
  cartCount, 
  onCartClick, 
  isAdmin, 
  onToggleAdmin,
  searchQuery,
  onSearchChange
}) => {
  useEffect(() => {
    const initGoogleSignIn = () => {
      /* global google */
      if (typeof window !== 'undefined' && (window as any).google?.accounts?.id) {
        (window as any).google.accounts.id.initialize({
          client_id: "710651034440-8unm6qu7v7h8p3m0p1q8p7q8p7q8p7q8.apps.googleusercontent.com",
          callback: (response: any) => {
            try {
              const decoded: any = jwtDecode(response.credential);
              onLogin({
                id: decoded.sub,
                name: decoded.name,
                email: decoded.email,
                picture: decoded.picture
              });
            } catch (err) {
              console.error("JWT Decode failed", err);
            }
          },
          auto_select: false,
        });

        if (!user) {
          const btnElem = document.getElementById("googleBtn");
          if (btnElem) {
            (window as any).google.accounts.id.renderButton(
              btnElem,
              { theme: "outline", size: "large", shape: "pill", text: "signin_with" }
            );
          }
        }
      }
    };

    // Retry initialization if script not ready
    const interval = setInterval(() => {
      if ((window as any).google?.accounts?.id) {
        initGoogleSignIn();
        clearInterval(interval);
      }
    }, 100);

    return () => clearInterval(interval);
  }, [user, onLogin]);

  return (
    <header className="sticky top-0 z-40 glass-effect border-b border-slate-200">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-20 gap-4">
          <div className="flex items-center gap-2 shrink-0">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <i className="fas fa-utensils"></i>
            </div>
            <div className="hidden md:block">
              <span className="text-lg font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-violet-600">
                Dhruv Restaurants
              </span>
              {user && (
                <div className="flex items-center gap-1.5 mt-[-2px]">
                  <span className="flex h-1.5 w-1.5 rounded-full bg-green-500"></span>
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Connected</span>
                </div>
              )}
            </div>
          </div>

          <div className="flex-1 max-w-md relative">
            <i className="fas fa-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
            <input 
              type="text"
              placeholder="Search dishes..."
              value={searchQuery}
              onChange={(e) => onSearchChange(e.target.value)}
              className="w-full bg-slate-100/50 border-none rounded-2xl py-2.5 pl-11 pr-4 focus:ring-2 focus:ring-indigo-600 transition-all outline-none text-sm"
            />
          </div>

          <div className="flex items-center gap-3">
            {user ? (
              <div className="flex items-center gap-2 lg:gap-3 bg-white border border-slate-200 p-1 pr-3 rounded-full shadow-sm">
                <img src={user.picture} alt={user.name} className="w-8 h-8 rounded-full border border-slate-100 shadow-sm" />
                <div className="hidden lg:block text-left">
                  <p className="text-[10px] font-black text-slate-800 leading-none truncate max-w-[60px]">{user.name.split(' ')[0]}</p>
                </div>
                <button 
                  onClick={onLogout}
                  className="w-6 h-6 rounded-full flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-red-50 transition-all"
                  title="Sign Out"
                >
                  <i className="fas fa-sign-out-alt text-[10px]"></i>
                </button>
              </div>
            ) : (
              <div id="googleBtn" className="h-10 min-w-[40px]"></div>
            )}

            {user && (
              <button 
                onClick={onToggleAdmin}
                className={`px-4 py-2 rounded-xl font-bold text-xs transition-all h-10 flex items-center gap-2 ${
                  isAdmin 
                  ? 'bg-slate-900 text-white shadow-xl shadow-slate-200' 
                  : 'bg-white text-slate-600 border border-slate-200 hover:border-indigo-600 hover:text-indigo-600'
                }`}
              >
                <i className={`fas ${isAdmin ? 'fa-store' : 'fa-cog'}`}></i>
                <span className="hidden sm:inline">{isAdmin ? 'Shop' : 'Admin'}</span>
              </button>
            )}

            {!user && (
               <div className="hidden lg:flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest mr-2">
                 <i className="fas fa-lock text-[8px]"></i>
                 Login for Admin
               </div>
            )}

            <button 
              onClick={onCartClick}
              className="relative p-2.5 bg-white border border-slate-200 rounded-xl text-slate-600 hover:text-indigo-600 hover:border-indigo-100 transition-all shadow-sm h-10 w-10 flex items-center justify-center"
            >
              <i className="fas fa-shopping-bag text-lg"></i>
              {cartCount > 0 && (
                <span className="absolute -top-1 -right-1 inline-flex items-center justify-center px-2 py-1 text-[10px] font-bold leading-none text-white bg-indigo-600 rounded-full border-2 border-white">
                  {cartCount}
                </span>
              )}
            </button>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;

import React, { useState, useEffect, useCallback } from 'react';
import { FoodItem, Category, CartItem, CustomerRecord, User } from './types';
import { INITIAL_FOOD_ITEMS } from './constants';
import { generateAppetizingMenu } from './services/geminiService';
import Header from './components/Header';
import CategoryFilter from './components/CategoryFilter';
import FoodCard from './components/FoodCard';
import Cart from './components/Cart';
import InvoiceModal from './components/InvoiceModal';
import AdminDashboard from './components/AdminDashboard';
import FoodFormModal from './components/FoodFormModal';

const App: React.FC = () => {
  // Helper to get keys based on current local user state
  const getStorageKeys = (currentUser: User | null) => {
    const suffix = currentUser ? currentUser.id : 'guest';
    return {
      menu: `dhruv_menu_${suffix}`,
      history: `dhruv_history_${suffix}`
    };
  };

  // 1. Initialize User
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('dhruv_user');
    return saved ? JSON.parse(saved) : null;
  });

  // 2. Initialize Data synchronously from the correct bucket
  const [foodItems, setFoodItems] = useState<FoodItem[]>(() => {
    const keys = getStorageKeys(user);
    const saved = localStorage.getItem(keys.menu);
    return saved ? JSON.parse(saved) : INITIAL_FOOD_ITEMS;
  });

  const [customerHistory, setCustomerHistory] = useState<CustomerRecord[]>(() => {
    const keys = getStorageKeys(user);
    const saved = localStorage.getItem(keys.history);
    return saved ? JSON.parse(saved) : [];
  });

  // 3. Handle data migration/switch when user changes
  useEffect(() => {
    const keys = getStorageKeys(user);
    const savedMenu = localStorage.getItem(keys.menu);
    const savedHistory = localStorage.getItem(keys.history);

    setFoodItems(savedMenu ? JSON.parse(savedMenu) : INITIAL_FOOD_ITEMS);
    setCustomerHistory(savedHistory ? JSON.parse(savedHistory) : []);

    if (user) {
      localStorage.setItem('dhruv_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('dhruv_user');
    }
  }, [user]);

  // 4. Persistence effects - watch for changes and save immediately
  useEffect(() => {
    const keys = getStorageKeys(user);
    localStorage.setItem(keys.menu, JSON.stringify(foodItems));
  }, [foodItems, user]);

  useEffect(() => {
    const keys = getStorageKeys(user);
    localStorage.setItem(keys.history, JSON.stringify(customerHistory));
  }, [customerHistory, user]);

  const [activeCategory, setActiveCategory] = useState<Category>(Category.All);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isInvoiceOpen, setIsInvoiceOpen] = useState(false);
  const [isAdminView, setIsAdminView] = useState(false);
  const [isEnhancing, setIsEnhancing] = useState(false);

  const [isFoodModalOpen, setIsFoodModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<FoodItem | null>(null);

  const filteredItems = foodItems.filter(item => {
    const matchesCategory = activeCategory === Category.All || item.category === activeCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         item.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const addToCart = (item: FoodItem, size: 'Half' | 'Full') => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id && i.selectedSize === size);
      if (existing) {
        return prev.map(i => (i.id === item.id && i.selectedSize === size) ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { ...item, quantity: 1, selectedSize: size }];
    });
    showToast(`Added ${item.name} (${size}) to bag! 😋`);
  };

  const showToast = (msg: string) => {
    const existing = document.getElementById('bistro-toast');
    if (existing) existing.remove();
    const toast = document.createElement('div');
    toast.id = 'bistro-toast';
    toast.className = 'fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-[2rem] shadow-2xl z-[100] font-black uppercase tracking-widest text-[10px] animate-in fade-in slide-in-from-bottom-4 duration-300 border border-white/10 backdrop-blur-xl';
    toast.textContent = msg;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.classList.replace('animate-in', 'animate-out');
      toast.classList.add('fade-out', 'slide-out-to-bottom-4');
      setTimeout(() => toast.remove(), 300);
    }, 2500);
  };

  const updateCartQuantity = (id: string, delta: number, size: 'Half' | 'Full') => {
    setCart(prev => prev.map(item => {
      if (item.id === id && item.selectedSize === size) {
        return { ...item, quantity: Math.max(0, item.quantity + delta) };
      }
      return item;
    }).filter(item => item.quantity > 0));
  };

  const saveFoodItem = (item: FoodItem) => {
    setFoodItems(prev => {
      const exists = prev.find(i => i.id === item.id);
      if (exists) {
        return prev.map(i => i.id === item.id ? item : i);
      }
      return [item, ...prev];
    });
    showToast(editingItem ? 'Dish Refined! ✨' : 'New Dish Launched! 🚀');
    setIsFoodModalOpen(false);
    setEditingItem(null);
  };

  const deleteFoodItem = (id: string) => {
    if (confirm('Permanently remove this dish from the menu?')) {
      setFoodItems(prev => prev.filter(i => i.id !== id));
      showToast('Dish Discontinued 🗑️');
    }
  };

  const enhanceMenu = async () => {
    if (isEnhancing) return;
    setIsEnhancing(true);
    const enhanced = await generateAppetizingMenu(JSON.stringify(foodItems));
    if (enhanced) {
      setFoodItems(enhanced);
      showToast('AI Intelligence Applied! ✨');
    }
    setIsEnhancing(false);
  };

  const handleRecordSaved = (record: CustomerRecord) => {
    setCustomerHistory(prev => [record, ...prev]);
  };

  return (
    <div className="min-h-screen pb-24 lg:pb-0 bg-slate-50/50">
      <Header 
        user={user}
        onLogin={setUser}
        onLogout={() => { setUser(null); setIsAdminView(false); }}
        cartCount={cart.reduce((sum, item) => sum + item.quantity, 0)} 
        onCartClick={() => setIsCartOpen(true)}
        isAdmin={isAdminView}
        onToggleAdmin={() => setIsAdminView(!isAdminView)}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
      />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-16">
        {isAdminView ? (
          <AdminDashboard 
            items={foodItems}
            history={customerHistory}
            onAddItem={() => { setEditingItem(null); setIsFoodModalOpen(true); }}
            onEditItem={(item) => { setEditingItem(item); setIsFoodModalOpen(true); }}
            onDeleteItem={deleteFoodItem}
          />
        ) : (
          <>
            <section className="relative rounded-[4rem] bg-indigo-600 p-10 md:p-24 mb-20 overflow-hidden shadow-[0_40px_80px_-20px_rgba(79,70,229,0.3)]">
              <div className="relative z-10 max-w-3xl">
                <div className="flex items-center gap-3 px-5 py-2.5 rounded-full bg-white/10 backdrop-blur-md text-white text-[10px] font-black mb-10 w-fit border border-white/20 uppercase tracking-[0.3em]">
                  <span className="flex h-2.5 w-2.5 rounded-full bg-green-400 animate-pulse"></span>
                  Kitchen is Live
                </div>
                <h1 className="text-6xl md:text-8xl font-black text-white mb-10 leading-[0.95] tracking-tighter italic">
                  Culinary <br/>Art, <span className="text-indigo-200">Served.</span>
                </h1>
                <div className="flex flex-wrap gap-5">
                  <button 
                    onClick={() => document.getElementById('menu-section')?.scrollIntoView({ behavior: 'smooth' })}
                    className="px-12 py-6 bg-white text-indigo-600 rounded-[2.5rem] font-black hover:scale-105 transition-all shadow-2xl active:scale-95 text-lg flex items-center gap-3"
                  >
                    Explore Menu <i className="fas fa-chevron-right text-sm"></i>
                  </button>
                  <button 
                    onClick={enhanceMenu}
                    disabled={isEnhancing}
                    className="px-10 py-6 bg-white/10 text-white rounded-[2.5rem] font-black hover:bg-white/20 border border-white/20 transition-all flex items-center gap-3 active:scale-95"
                  >
                    {isEnhancing ? <i className="fas fa-spinner fa-spin"></i> : <i className="fas fa-magic"></i>}
                    AI Enhancement
                  </button>
                </div>
              </div>
              <div className="absolute top-0 right-0 w-1/2 h-full hidden lg:block pointer-events-none">
                <img src="https://images.unsplash.com/photo-1555396273-367ea4eb4db5?q=80&w=1000&auto=format&fit=crop" className="absolute right-[-20%] top-1/2 -translate-y-1/2 w-[130%] h-[140%] object-cover opacity-40 mix-blend-screen rotate-6 blur-[1px]" alt="Food Decor" />
              </div>
            </section>

            <section id="menu-section">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-20">
                <div>
                  <h2 className="text-5xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">The Menu</h2>
                  <p className="text-slate-500 font-bold mt-4 uppercase tracking-[0.1em] text-xs">A selection of chef's daily creations.</p>
                </div>
                <CategoryFilter activeCategory={activeCategory} onCategoryChange={setActiveCategory} />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-12">
                {filteredItems.map(item => (
                  <FoodCard key={item.id} item={item} onAddToCart={addToCart} />
                ))}
              </div>

              {filteredItems.length === 0 && (
                <div className="text-center py-48 bg-white rounded-[4rem] border border-dashed border-slate-200">
                  <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-8 text-slate-200 text-5xl">
                    <i className="fas fa-cookie-bite"></i>
                  </div>
                  <h3 className="text-2xl font-black text-slate-800 mb-3 tracking-tighter italic">Nothing Found!</h3>
                </div>
              )}
            </section>
          </>
        )}
      </main>

      <Cart isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} items={cart} onUpdateQuantity={updateCartQuantity} onCheckout={() => { setIsCartOpen(false); setIsInvoiceOpen(true); }} />

      {isInvoiceOpen && (
        <InvoiceModal cart={cart} onClose={() => setIsInvoiceOpen(false)} onClearCart={() => setCart([])} onRecordSaved={handleRecordSaved} />
      )}

      {isFoodModalOpen && (
        <FoodFormModal item={editingItem} onClose={() => setIsFoodModalOpen(false)} onSave={saveFoodItem} />
      )}
    </div>
  );
};

export default App;

import React, { useEffect } from 'react';
